<title>Opening hours</title>
<meta name="idea" content="Weekly hours as a day-by-day timeline with today highlighted">
<main style="padding:1rem">
  <header>
    <h1>Opening hours</h1>
    <p><small>Crumb &amp; Co., Main Street 12</small></p>
  </header>

  <article data-part="1">
    <h2>This week</h2>
    <div id="week" style="display:grid;gap:.5rem"></div>
  </article>

  <section data-part="2">
    <p><small id="status">Open now until 15:00</small></p>
    <button data-action="@visit: opening hours and address">Back to visit</button>
  </section>

  <nav data-part="3" style="margin-top:1rem">
    <a data-action="@menu: the full list of breads and pastries">Menu</a> ·
    <a data-action="@contact: send a message to the bakery">Contact</a>
  </nav>
</main>
<script>
  const days = [
    ['Mon', '07:00', '15:00'],
    ['Tue', '07:00', '15:00'],
    ['Wed', '07:00', '15:00'],
    ['Thu', '07:00', '15:00'],
    ['Fri', '07:00', '17:00'],
    ['Sat', '08:00', '14:00'],
    ['Sun', null, null]
  ];
  const today = (new Date().getDay() + 6) % 7;
  const week = document.getElementById('week');
  days.forEach(([name, open, close], i) => {
    const row = document.createElement('div');
    row.style.cssText = 'display:flex;align-items:center;gap:.75rem;padding:.4rem .6rem;border-radius:.5rem;' +
      (i === today ? 'background:var(--pico-mark-background-color,#fff3c4);font-weight:bold' : '');
    const label = document.createElement('span');
    label.style.width = '3rem';
    label.textContent = name;
    const bar = document.createElement('div');
    bar.style.cssText = 'position:relative;flex:1;height:.9rem;background:#eee;border-radius:.45rem';
    if (open) {
      const start = (parseInt(open) - 7) / 12 * 100;
      const end = (parseInt(close) - 7) / 12 * 100;
      const fill = document.createElement('div');
      fill.style.cssText = `position:absolute;top:0;bottom:0;left:${start}%;width:${end - start}%;background:#c98b3a;border-radius:.45rem`;
      bar.appendChild(fill);
    }
    const time = document.createElement('small');
    time.textContent = open ? `${open} to ${close}` : 'Closed';
    row.append(label, bar, time);
    week.appendChild(row);
  });
  const status = document.getElementById('status');
  const hour = new Date().getHours();
  const todayHours = days[today];
  if (todayHours[1] && hour >= parseInt(todayHours[1]) && hour < parseInt(todayHours[2])) {
    status.textContent = `Open now until ${todayHours[2]}`;
  } else if (todayHours[1]) {
    status.textContent = `Closed now, today ${todayHours[1]} to ${todayHours[2]}`;
  } else {
    status.textContent = 'Closed today';
  }
</script>

